                        >
                            {translate('workspace.changeOwner.addPaymentCardPrivacy')}
                        </TextLink>{' '}
                        {translate('workspace.changeOwner.addPaymentCardReadAndAcceptTextPart2')}
                    </Text>
                    <Section
